/** The collections of the database, as Mongoose models. They reflect it: Mongoose never creates collections or indexes with them. */
import { Schema, type Connection, type Model } from 'mongoose'

/** A document as the driver gives it, by the stored names of its fields */
export type Stored = Record<string, unknown>

/** The model of every collection */
export interface Models {
  users: Model<Stored>
  notes: Model<Stored>
}

/** Defines the model of every collection on `connection`. */
export function defineModels(connection: Connection): Models {
  /** The 'users' collection. */
  const users = new Schema(
    {
      _id: Number,
      email: { type: String, required: true },
    },
    { collection: 'users', versionKey: false, minimize: false, autoIndex: false, autoCreate: false },
  )
  users.index({ email: 1 }, { unique: true, name: 'uq_users_email' })

  /** The 'notes' collection. */
  const notes = new Schema(
    {
      _id: Number,
      text: { type: String, required: true },
      authorId: { type: Number, required: true },
    },
    { collection: 'notes', versionKey: false, minimize: false, autoIndex: false, autoCreate: false },
  )
  notes.index({ authorId: 1 }, { name: 'ix_notes_authorId' })

  return {
    users: connection.model<Stored>('User', users as unknown as Schema<Stored>),
    notes: connection.model<Stored>('Note', notes as unknown as Schema<Stored>),
  }
}

