/** Repository of the "notes" table: reads and writes rows, and decides nothing. */
import type { ClientSession } from 'mongoose'
import { plain, refusal, type Db } from '../database.js'
import { Note } from '../entities/note.js'
import type { Stored } from '../models.js'
import type { Page } from '../paging.js'

/** Where notes rows are kept. Services depend only on this interface. */
export interface NoteRepository {
  findById(id: number): Promise<Note | null>
  list(offset?: number, limit?: number): Promise<Page<Note>>
  listByAuthorId(authorId: number): Promise<Note[]>
  insert(entity: Note): Promise<Note>
  update(entity: Note): Promise<Note>
  delete(entity: Note): Promise<void>
}

/** The key of a row, as a list of its key values. */
function keyOf(row: Note): unknown[] {
  return [row.id]
}

/** Orders two keys value by value. */
function compareKeys(a: unknown[], b: unknown[]): number {
  for (let index = 0; index < a.length; index++) {
    const x = a[index] as number | string
    const y = b[index] as number | string
    if (x < y) return -1
    if (x > y) return 1
  }
  return 0
}

/** The values each entity was read with, by the stored names of its fields: a change writes only those that differ. */
const loaded = new WeakMap<Note, Record<string, string>>()

/** The fields of an entity a change may write. */
function changeable(entity: Note): Stored {
  return {
    text: entity.text,
    authorId: entity.authorId,
  }
}

/** The same fields as text, to compare them later. */
const snapshot = (entity: Note): Record<string, string> =>
  Object.fromEntries(Object.entries(changeable(entity)).map(([name, value]) => [name, JSON.stringify(value ?? null)]))

/** The Note of a document; a field it does not have is null. */
function toEntity(document: Stored): Note {
  const entity = Object.assign(new Note(), {
    id: (plain(document._id) ?? null) as number,
    text: (plain(document.text) ?? null) as string,
    authorId: (plain(document.authorId) ?? null) as number,
  })
  loaded.set(entity, snapshot(entity))
  return entity
}

/** The fields of a new document; those left empty are not stored, and take their default. */
function storedValues(entity: Note): Stored {
  const values: Stored = {
    _id: entity.id,
    text: entity.text,
    authorId: entity.authorId,
  }
  return Object.fromEntries(Object.entries(values).filter(([, value]) => value !== undefined && value !== null))
}

/** What a change writes and what it removes: only the fields that are not as they were read. */
function changesOf(entity: Note): { $set: Stored; $unset: Stored } {
  const before = loaded.get(entity)
  const $set: Stored = {}
  const $unset: Stored = {}
  for (const [name, value] of Object.entries(changeable(entity))) {
    if (before?.[name] === JSON.stringify(value ?? null)) continue
    if (value === undefined || value === null) $unset[name] = ''
    else $set[name] = value
  }
  return { $set, $unset }
}

/** Keeps notes documents in the database, through Mongoose. Every write is stored at once. */
export class MongoNoteRepository implements NoteRepository {
  constructor(
    private readonly db: Db,
    private readonly session: ClientSession | null = null,
  ) {}

  /** The row with this primary key, or null. */
  async findById(id: number): Promise<Note | null> {
    const foundDocument = await this.db.models.notes.findOne({ _id: id }).session(this.session).lean<Stored>()
    return foundDocument === null ? null : toEntity(foundDocument)
  }

  /** At most `limit` rows from `offset`, by primary key, and how many there are. */
  async list(offset: number = 0, limit: number = 50): Promise<Page<Note>> {
    const documents = await this.db.models.notes.find({}).sort({ _id: 1 }).skip(offset).limit(limit).session(this.session).lean<Stored[]>()
    const total = await this.db.models.notes.countDocuments({}).session(this.session)
    return { items: documents.map(toEntity), total, offset, limit }
  }

  /** Rows with this authorId, by primary key. */
  async listByAuthorId(authorId: number): Promise<Note[]> {
    return (await this.db.models.notes.find({ authorId }).sort({ _id: 1 }).session(this.session).lean<Stored[]>()).map(toEntity)
  }

  /** Stores a new row; the values the database fills are read back. */
  async insert(entity: Note): Promise<Note> {
    try {
      const [document] = await this.db.models.notes.create([storedValues(entity)], { session: this.session ?? undefined })
      const stored = toEntity(document.toObject() as Stored)
      Object.assign(entity, stored)
      loaded.set(entity, loaded.get(stored)!)
      return entity
    } catch (error) {
      throw refusal('Note', error)
    }
  }

  /** Stores the changes made to a row read from this repository. */
  async update(entity: Note): Promise<Note> {
    try {
      await this.db.models.notes.updateOne({ _id: entity.id }, changesOf(entity), { session: this.session ?? undefined, runValidators: true, timestamps: false })
    } catch (error) {
      throw refusal('Note', error)
    }
    loaded.set(entity, snapshot(entity))
    return entity
  }

  /** Removes a row read from this repository. */
  async delete(entity: Note): Promise<void> {
    try {
      await this.db.models.notes.deleteOne({ _id: entity.id }).session(this.session)
    } catch (error) {
      throw refusal('Note', error)
    }
  }
}

/** Keeps notes rows in memory, for tests and for trying the services without a database. */
export class MemoryNoteRepository implements NoteRepository {
  private readonly rows = new Map<string, Note>()

  private visible(): Note[] {
    return [...this.rows.values()].filter((row) => true).sort((a, b) => compareKeys(keyOf(a), keyOf(b)))
  }

  /** The row with this primary key, or null. */
  async findById(id: number): Promise<Note | null> {
    return this.visible().find((row) => row.id === id) ?? null
  }

  /** At most `limit` rows from `offset`, by primary key, and how many there are. */
  async list(offset: number = 0, limit: number = 50): Promise<Page<Note>> {
    const rows = this.visible()
    return { items: rows.slice(offset, offset + limit), total: rows.length, offset, limit }
  }

  /** Rows with this authorId, by primary key. */
  async listByAuthorId(authorId: number): Promise<Note[]> {
    return this.visible().filter((row) => row.authorId === authorId)
  }

  /** Stores a new row; the values the database fills are read back. */
  async insert(entity: Note): Promise<Note> {
    this.rows.set(JSON.stringify(keyOf(entity)), entity)
    return entity
  }

  /** Stores the changes made to a row read from this repository. */
  async update(entity: Note): Promise<Note> {
    this.rows.set(JSON.stringify(keyOf(entity)), entity)
    return entity
  }

  /** Removes a row read from this repository. */
  async delete(entity: Note): Promise<void> {
    this.rows.delete(JSON.stringify(keyOf(entity)))
  }
}

