    const foundDocument = await this.db.models.users.findOne({ email }).session(this.session).lean<Stored>()
    return foundDocument === null ? null : toEntity(foundDocument)
  }

  /** Stores a new row; the values the database fills are read back. */
  async insert(entity: User): Promise<User> {
    try {
      const [document] = await this.db.models.users.create([storedValues(entity)], { session: this.session ?? undefined })
      const stored = toEntity(document.toObject() as Stored)
      Object.assign(entity, stored)
      loaded.set(entity, loaded.get(stored)!)
      return entity
    } catch (error) {
      throw refusal('User', error)
    }
  }

  /** Stores the changes made to a row read from this repository. */
  async update(entity: User): Promise<User> {
    try {
      await this.db.models.users.updateOne({ _id: entity.id }, changesOf(entity), { session: this.session ?? undefined, runValidators: true, timestamps: false })
    } catch (error) {
      throw refusal('User', error)
    }
    loaded.set(entity, snapshot(entity))
    return entity
  }

  /** Removes a row read from this repository. */
  async delete(entity: User): Promise<void> {
    try {
      await this.db.models.users.deleteOne({ _id: entity.id }).session(this.session)
    } catch (error) {
      throw refusal('User', error)
    }
  }
}

