import type { NoteCreate, NoteRead, NoteUpdate } from '../dtos/note.js'
import { Note } from '../entities/note.js'
import { NotFoundError, ValidationFailedError, type FieldError } from '../errors.js'
import type { Page } from '../paging.js'
import type { UnitOfWork } from '../unit-of-work.js'

/** Properties a client may send: the database fills the others */
const FIELDS = new Set(['id', 'text', 'authorId'])

/** Operations on notes. Repositories commit every write. */
export class NoteService {
  constructor(private readonly uow: UnitOfWork) {}

  /** Checks the values against the rules of the "notes" table, and the rows they point to; throws ValidationFailedError with every problem. */
  private async validate(uow: UnitOfWork, values: Partial<Record<string, unknown>>, current: Note | null): Promise<void> {
    const creating = current === null
    const errors: FieldError[] = []
    for (const name of Object.keys(values)) if (!FIELDS.has(name)) errors.push({ field: name, message: 'is not a field of Note' })
    if (!creating) for (const name of Object.keys(values)) if (['id'].includes(name)) errors.push({ field: name, message: 'cannot be changed' })
    {
      const value = values.id
      if (value == null) {
        if (creating || 'id' in values) errors.push({ field: '_id', message: 'is required' })
      }
    }
    {
      const value = values.text
      if (value == null) {
        if (creating || 'text' in values) errors.push({ field: 'text', message: 'is required' })
      }
    }
    {
      const value = values.authorId
      if (value == null) {
        if (creating || 'authorId' in values) errors.push({ field: 'authorId', message: 'is required' })
      }
    }
    {
      const authorId = 'authorId' in values ? values.authorId : current?.authorId
      if (authorId != null && (await uow.users.findById(authorId as number)) === null)
        errors.push({ field: 'authorId', message: 'no User has this key' })
    }
    if (errors.length > 0) throw new ValidationFailedError('Note', errors)
  }

  /** Every check before a write: the values, the rows they point to, the unique values. */
  private async check(uow: UnitOfWork, values: Partial<Record<string, unknown>>, current: Note | null): Promise<void> {
    await this.validate(uow, values, current)
  }

  /** The Note with this key; NotFoundError when there is none. */
  private async find(uow: UnitOfWork, id: number): Promise<Note> {
    const entity = await uow.notes.findById(id)
    if (entity === null) throw new NotFoundError('Note', id)
    return entity
  }

  /** The Note as services return it. */
  private static read(entity: Note): NoteRead {
    return { id: entity.id, text: entity.text, authorId: entity.authorId }
  }

  /** Stores a new Note after checking it. */
  async createNote(data: NoteCreate): Promise<NoteRead> {
    const values: Partial<Record<string, unknown>> = Object.fromEntries(Object.entries(data).filter(([, value]) => value !== undefined))
    return this.uow.transaction(async (uow) => {
      await this.check(uow, values, null)
      const created = await uow.notes.insert(Object.assign(new Note(), values))
      return NoteService.read(created)
    })
  }

  /** The Note with this key; NotFoundError when there is none. */
  async getNote(id: number): Promise<NoteRead> {
    return NoteService.read(await this.find(this.uow, id))
  }

  /** A page of notes, by primary key. */
  async listNotes(offset = 0, limit = 50): Promise<Page<NoteRead>> {
    const page = await this.uow.notes.list(offset, limit)
    return { ...page, items: page.items.map((entity) => NoteService.read(entity)) }
  }

  /** Changes the given values of a Note. */
  async updateNote(id: number, data: NoteUpdate): Promise<NoteRead> {
    const values: Partial<Record<string, unknown>> = Object.fromEntries(Object.entries(data).filter(([, value]) => value !== undefined))
    return this.uow.transaction(async (uow) => {
      const current = await this.find(uow, id)
      await this.check(uow, values, current)
      Object.assign(current, values)
      const updated = await uow.notes.update(current)
      return NoteService.read(updated)
    })
  }

  /** Deletes a Note. */
  async deleteNote(id: number): Promise<void> {
    return this.uow.transaction(async (uow) => {
      const current = await this.find(uow, id)
      await uow.notes.delete(current)
    })
  }

  /** The notes with this authorId. */
  async listNotesByAuthorId(authorId: number): Promise<NoteRead[]> {
    return (await this.uow.notes.listByAuthorId(authorId)).map((entity) => NoteService.read(entity))
  }
}

